import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

export default function AdminDashboard() {
  const { logout } = useAuth();
  const navigate = useNavigate();
  const [stats, setStats] = useState({
    totalStudents: 0,
    totalQuestions: 0,
    totalTopics: 0,
    totalMockTests: 0
  });

  useEffect(() => {
    api.get('/admin/stats')
      .then(res => setStats(res.data))
      .catch(() => {});
  }, []);

  return (
    <div style={{ display: 'flex', minHeight: '100vh' }}>
      
      {/* Sidebar */}
      <div style={{
        width: '240px', background: '#1a1a2e', color: 'white',
        padding: '1.5rem 0', display: 'flex', flexDirection: 'column'
      }}>
        <div style={{ padding: '0 1.5rem 1.5rem', borderBottom: '1px solid #ffffff20' }}>
          <h2 style={{ color: 'white', fontSize: '1.1rem' }}>👨‍💼 Admin Panel</h2>
        </div>
        <nav style={{ padding: '1rem 0', flex: 1 }}>
          <p style={{ color: '#ffffff60', fontSize: '0.7rem', 
            padding: '0 1.5rem', marginBottom: '0.5rem' }}>MANAGE</p>

          <div onClick={() => navigate('/admin/dashboard')}
            style={{ padding: '0.8rem 1.5rem', cursor: 'pointer',
              background: '#ffffff20', color: 'white',
              display: 'flex', alignItems: 'center', gap: '0.7rem' }}>
            📊 Dashboard
          </div>

          <div onClick={() => navigate('/admin/questions')}
            style={{ padding: '0.8rem 1.5rem', cursor: 'pointer',
              color: '#ffffff90', display: 'flex', 
              alignItems: 'center', gap: '0.7rem' }}
            onMouseEnter={e => e.currentTarget.style.background = '#ffffff10'}
            onMouseLeave={e => e.currentTarget.style.background = 'transparent'}>
            ❓ Questions
          </div>

          <div onClick={() => navigate('/admin/students')}
            style={{ padding: '0.8rem 1.5rem', cursor: 'pointer',
              color: '#ffffff90', display: 'flex',
              alignItems: 'center', gap: '0.7rem' }}
            onMouseEnter={e => e.currentTarget.style.background = '#ffffff10'}
            onMouseLeave={e => e.currentTarget.style.background = 'transparent'}>
            🎓 Students
          </div>

          <p style={{ color: '#ffffff60', fontSize: '0.7rem',
            padding: '1rem 1.5rem 0.5rem' }}>ACCOUNT</p>

          <div onClick={() => { logout(); navigate('/login'); }}
            style={{ padding: '0.8rem 1.5rem', cursor: 'pointer',
              color: '#ff6b6b', display: 'flex',
              alignItems: 'center', gap: '0.7rem' }}
            onMouseEnter={e => e.currentTarget.style.background = '#ffffff10'}
            onMouseLeave={e => e.currentTarget.style.background = 'transparent'}>
            🚪 Logout
          </div>
        </nav>
      </div>

      {/* Main Content */}
      <div style={{ flex: 1, padding: '2rem', background: '#f8f9fa' }}>
        <div style={{ marginBottom: '2rem' }}>
          <h1 style={{ fontSize: '1.8rem', fontWeight: 700 }}>📊 Admin Dashboard</h1>
          <p style={{ color: '#666' }}>Manage your PlacementTrack platform</p>
        </div>

        {/* Stats Cards */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1.5rem', marginBottom: '2rem' }}>
          
          <div style={{ background: 'white', borderRadius: '12px',
            padding: '1.5rem', borderTop: '4px solid #6c63ff',
            boxShadow: '0 2px 10px rgba(0,0,0,0.08)' }}>
            <div style={{ fontSize: '2rem' }}>🎓</div>
            <p style={{ color: '#666', marginTop: '0.5rem' }}>Total Students</p>
            <p style={{ fontSize: '2rem', fontWeight: 700, color: '#6c63ff' }}>
              {stats.totalStudents}
            </p>
          </div>

          <div style={{ background: 'white', borderRadius: '12px',
            padding: '1.5rem', borderTop: '4px solid #00b4d8',
            boxShadow: '0 2px 10px rgba(0,0,0,0.08)' }}>
            <div style={{ fontSize: '2rem' }}>❓</div>
            <p style={{ color: '#666', marginTop: '0.5rem' }}>Total Questions</p>
            <p style={{ fontSize: '2rem', fontWeight: 700, color: '#00b4d8' }}>
              {stats.totalQuestions}
            </p>
          </div>

          <div style={{ background: 'white', borderRadius: '12px',
            padding: '1.5rem', borderTop: '4px solid #00b894',
            boxShadow: '0 2px 10px rgba(0,0,0,0.08)' }}>
            <div style={{ fontSize: '2rem' }}>📚</div>
            <p style={{ color: '#666', marginTop: '0.5rem' }}>Total Topics</p>
            <p style={{ fontSize: '2rem', fontWeight: 700, color: '#00b894' }}>
              {stats.totalTopics}
            </p>
          </div>

          <div style={{ background: 'white', borderRadius: '12px',
            padding: '1.5rem', borderTop: '4px solid #f77f00',
            boxShadow: '0 2px 10px rgba(0,0,0,0.08)' }}>
            <div style={{ fontSize: '2rem' }}>📝</div>
            <p style={{ color: '#666', marginTop: '0.5rem' }}>Mock Tests Taken</p>
            <p style={{ fontSize: '2rem', fontWeight: 700, color: '#f77f00' }}>
              {stats.totalMockTests}
            </p>
          </div>
        </div>

        {/* Quick Actions */}
        <h2 style={{ marginBottom: '1rem', fontSize: '1.3rem', fontWeight: 700 }}>
          ⚡ Quick Actions
        </h2>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1rem' }}>
          
          <div onClick={() => navigate('/admin/questions')}
            style={{ background: 'white', borderRadius: '12px',
              padding: '1.5rem', cursor: 'pointer',
              boxShadow: '0 2px 10px rgba(0,0,0,0.08)',
              transition: 'transform 0.2s' }}
            onMouseEnter={e => e.currentTarget.style.transform = 'translateY(-2px)'}
            onMouseLeave={e => e.currentTarget.style.transform = 'translateY(0)'}>
            <div style={{ fontSize: '2rem' }}>➕</div>
            <h3 style={{ marginTop: '0.5rem' }}>Add Questions</h3>
            <p style={{ color: '#666', fontSize: '0.85rem' }}>Add new practice questions</p>
          </div>

          <div onClick={() => navigate('/admin/students')}
            style={{ background: 'white', borderRadius: '12px',
              padding: '1.5rem', cursor: 'pointer',
              boxShadow: '0 2px 10px rgba(0,0,0,0.08)',
              transition: 'transform 0.2s' }}
            onMouseEnter={e => e.currentTarget.style.transform = 'translateY(-2px)'}
            onMouseLeave={e => e.currentTarget.style.transform = 'translateY(0)'}>
            <div style={{ fontSize: '2rem' }}>👥</div>
            <h3 style={{ marginTop: '0.5rem' }}>View Students</h3>
            <p style={{ color: '#666', fontSize: '0.85rem' }}>Monitor student progress</p>
          </div>
        </div>
      </div>
    </div>

  );
}
